ee:variables.ee:set-variable:
%dw 2.0
output application/xml

---
{
  'Invoice'
  @(
    "xmlns:cbc": "http://www.oasis-open.org/committees/ubl/schema/xsd/CommonBasicComponents-2",
    "xmlns:cac": "http://www.oasis-open.org/committees/ubl/schema/xsd/CommonAggregateComponents-2"): { 

    'cbc:ID': payload.eGovData.DataArea.Transaction.Num,
    'cbc:InvoiceTypeCode': payload.eGovData.DataArea.Transaction.Type,
    'cbc:IssueDate': payload.eGovData.DataArea.Transaction.Date,
    'cbc:DocumentCurrencyCode': payload.eGovData.DataArea.Transaction.CurrencyCode,
    'cbc:DueDate': payload.eGovData.DataArea.Transaction.TransactionReferences.Ref1,
    'cbc:BuyerReference': payload.eGovData.DataArea.Transaction.TransactionReferences.Ref2,
    'cbc:Note': payload.eGovData.DataArea.Transaction.TransactionReferences.Ref3,
    'cac:OrderReference': {
      'cbc:ID': payload.eGovData.DataArea.Transaction.TransactionReferences.Ref18
    },
    'cac:AccountingSupplierParty': {
      'cac:Party': {
        'cac:PartyName': {
          'cbc:Name': payload.eGovData.DataArea.Transaction.Address1.Name
        },
        'cac:PostalAddress': {
          'cbc:StreetName': payload.eGovData.DataArea.Transaction.Address1.AddressLine1,
          'cbc:AdditionalStreetName': payload.eGovData.DataArea.Transaction.Address1.AddressLine2,
          'cbc:CityName': payload.eGovData.DataArea.Transaction.Address1.City,
          'cbc:CountrySubentity': payload.eGovData.DataArea.Transaction.Address1.State,
          'cbc:PostalZone': payload.eGovData.DataArea.Transaction.Address1.PostalCode,
          'cbc:Country': {
            'cbc:IdentificationCode': payload.eGovData.DataArea.Transaction.Address1.Country
          }
        },
        'cac:PartyTaxScheme': {
          'cbc:CompanyID': payload.eGovData.DataArea.Transaction.TaxReferences.Ref1,
          'cac:TaxScheme': {
            'cbc:ID': payload.eGovData.DataArea.Transaction.TaxReferences.Ref2
          }
        },
        'cac:PartyLegalEntity': {
          'cbc:RegistrationName': payload.eGovData.DataArea.Transaction.TaxReferences.Ref3,
          'cbc:CompanyID': {
            '@schemeID': payload.eGovData.DataArea.Transaction.TaxReferences.Ref4,
            '#': payload.eGovData.DataArea.Transaction.TaxReferences.Ref5
          }
        },
        'cac:PartyIdentification': {
          'cbc:ID': {
            '@schemeID': payload.eGovData.DataArea.Transaction.TaxReferences.Ref13,
            '#': payload.eGovData.DataArea.Transaction.TaxReferences.Ref14
          }
        },
        'cbc:EndpointID': {
          '@schemeID': payload.eGovData.DataArea.Transaction.TransactionReferences.Ref11,
          '#': payload.eGovData.DataArea.Transaction.TransactionReferences.Ref12
        }
      }
    },
    'cac:AccountingCustomerParty': {
      'cac:Party': {
        'cac:PartyName': {
          'cbc:Name': payload.eGovData.DataArea.Transaction.Address2.Name
        },
        'cac:PostalAddress': {
          'cbc:StreetName': payload.eGovData.DataArea.Transaction.Address2.AddressLine1,
          'cbc:AdditionalStreetName': payload.eGovData.DataArea.Transaction.Address2.AddressLine2,
          'cbc:CityName': payload.eGovData.DataArea.Transaction.Address2.City,
          'cbc:CountrySubentity': payload.eGovData.DataArea.Transaction.Address2.State,
          'cbc:PostalZone': payload.eGovData.DataArea.Transaction.Address2.PostalCode,
          'cbc:Country': {
            'cbc:IdentificationCode': payload.eGovData.DataArea.Transaction.Address2.Country
          }
        },
        'cac:PartyTaxScheme': {
          'cbc:CompanyID': payload.eGovData.DataArea.Transaction.TaxReferences.Ref6,
          'cac:TaxScheme': {
            'cbc:ID': payload.eGovData.DataArea.Transaction.TaxReferences.Ref7
          }
        },
        'cac:PartyLegalEntity': {
          'cbc:RegistrationName': payload.eGovData.DataArea.Transaction.TaxReferences.Ref8,
          'cbc:CompanyID': {
            '@schemeID': payload.eGovData.DataArea.Transaction.TaxReferences.Ref9,
            '#': payload.eGovData.DataArea.Transaction.TaxReferences.Ref10
          }
        },
        'cac:PartyIdentification': {
          'cbc:ID': {
            '@schemeID': payload.eGovData.DataArea.Transaction.TaxReferences.Ref11,
            '#': payload.eGovData.DataArea.Transaction.TaxReferences.Ref12
          }
        },
        'cbc:EndpointID': {
          '@schemeID': payload.eGovData.DataArea.Transaction.TransactionReferences.Ref13,
          '#': payload.eGovData.DataArea.Transaction.TransactionReferences.Ref14
        },
        'cac:Contact': {
          'cbc:Name': payload.eGovData.DataArea.Transaction.TransactionContacts.Ref1,
          'cbc:Telephone': payload.eGovData.DataArea.Transaction.TransactionContacts.Ref2,
          'cbc:ElectronicMail': payload.eGovData.DataArea.Transaction.TransactionContacts.Ref3
        }
      }
    },
    'cac:LegalMonetaryTotal': {
      'cbc:LineExtensionAmount': payload.eGovData.DataArea.Transaction.TransactionValues.Val1,
      'cbc:TaxExclusiveAmount': payload.eGovData.DataArea.Transaction.TransactionValues.Val2,
      'cbc:TaxInclusiveAmount': payload.eGovData.DataArea.Transaction.TransactionValues.Val3,
      'cbc:ChargeTotalAmount': payload.eGovData.DataArea.Transaction.TransactionValues.Val4,
      'cbc:PayableAmount': payload.eGovData.DataArea.Transaction.TransactionValues.Val5,
      'cbc:PrepaidAmount': payload.eGovData.DataArea.Transaction.TransactionValues.Val7,
      'cbc:PayableRoundingAmount': payload.eGovData.DataArea.Transaction.TransactionValues.Val8,
      'cbc:AllowanceTotalAmount': payload.eGovData.DataArea.Transaction.TransactionValues.Val9
    },
    'cac:TaxTotal': {
      'cbc:TaxAmount': payload.eGovData.DataArea.Transaction.TransactionValues.Val6,
      'cac:TaxSubtotal': {
        'cbc:TaxableAmount': payload.eGovData.DataArea.Transaction.TransactionSummary1.GroupValues.Val1,
        'cbc:TaxAmount': payload.eGovData.DataArea.Transaction.TransactionSummary1.GroupValues.Val2,
        'cac:TaxCategory': {
          'cbc:Percent': payload.eGovData.DataArea.Transaction.TransactionSummary1.GroupValues.Val3,
          'cbc:ID': payload.eGovData.DataArea.Transaction.TransactionSummary1.GroupTaxReferences.Ref1,
          'cac:TaxScheme': {
            'cbc:ID': payload.eGovData.DataArea.Transaction.TransactionSummary1.GroupTaxReferences.Ref2
          },
          'cbc:TaxExemptionReasonCode': payload.eGovData.DataArea.Transaction.TransactionSummary1.GroupTaxReferences.Ref3,
          'cbc:TaxExemptionReason': payload.eGovData.DataArea.Transaction.TransactionSummary1.GroupTaxReferences.Ref4
        }
      }
    },
    'cac:InvoiceLine': payload.eGovData.DataArea.Transaction.TransactionLine map (item) -> {
      'cbc:ID': item.LineNumber,
      'cbc:InvoicedQuantity': {
        '@unitCode': item.LineReferences.Ref1,
        '#': item.LineQuantities.Qty1
      },
      'cbc:LineExtensionAmount': item.LineValues.Val1,
      'cac:Price': {
        'cbc:PriceAmount': item.LineValues.Val2
      },
      'cac:InvoicePeriod': {
        'cbc:StartDate': item.LineDates.Date1,
        'cbc:EndDate': item.LineDates.Date2
      },
      'cac:Item': {
        'cbc:Description': item.Description,
        'cbc:Name': item.LineReferences.Ref4,
        'cac:StandardItemIdentification': {
          '@schemeID': item.LineReferences.Ref6,
          'cbc:ID': item.LineReferences.Ref7
        },
        'cac:OriginCountry': {
          'cbc:IdentificationCode': item.LineReferences.Ref8
        },
        'cac:CommodityClassification': {
          'cbc:ItemClassificationCode': {
            '@listID': item.LineReferences.Ref9,
            '#': item.LineReferences.Ref10
          }
        },
        'cac:ClassifiedTaxCategory': {
          'cbc:ID': item.LineTaxReferences.Ref1,
          'cbc:Percent': item.LineTaxReferences.Ref2,
          'cac:TaxScheme': {
            'cbc:ID': item.LineTaxReferences.Ref3
          }
        },
              'cac:AllowanceCharge': {
        'cbc:Amount': item.LineValues.Val3,
        'cbc:MultiplierFactorNumeric': item.LineValues.Val4,
        'cbc:AllowanceChargeReason': item.LineReferences.Ref11,
        'cbc:ChargeIndicator': item.LineReferences.Ref12,
        'cbc:AllowanceChargeReasonCode': item.LineReferences.Ref13,
        'cbc:AllowanceChargeReason': item.LineReferences.Ref14
      }
      }
    }
  }
}
